"""Regenerate the README "Where AI is used" section from ai/registry.py.

Usage: python scripts/readme.py [--check]
  default  rewrite the section between the AI-USED markers
  --check  write nothing; exit 1 if the README differs from what would be written
"""

from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(ROOT))

from ai.registry import CALLS, LAYERS  # noqa: E402

README = ROOT / "README.md"
START = (
    "<!-- AI-USED:START (generated by `python tasks.py readme` from ai/registry.py; "
    "do not hand-edit) -->"
)
END = "<!-- AI-USED:END -->"


def render() -> str:
    built = [c for c in CALLS if c.built]
    planned = [c for c in CALLS if not c.built]
    lines = [
        f"{len(built)} Claude calls are built, each loaded from a versioned prompt in "
        "`ai/prompts/` and run through one path (`ai/client.py`): structured output, prompt "
        "caching, bounded retries, a deterministic fallback and one audit row. "
        + (
            f"{len(planned)} more are specified but not built yet (calls "
            + " and ".join(str(c.id) for c in planned)
            + "): they have a prompt and a schema, and no code calls them. "
            if planned
            else ""
        )
        + "Everything below is read from `ai/registry.py`.",
        "",
        "| # | Call | Model | When |",
        "| --- | --- | --- | --- |",
    ]
    for c in CALLS:
        name = c.name if c.built else f"{c.name} (planned, not built)"
        lines.append(f"| {c.id} | {name} | `{c.model}` | {c.when} |")
    for c in CALLS:
        status = "" if c.built else " *Planned, not built: no code calls it yet.*"
        lines += ["", f"**Call {c.id}: {c.name}.** {c.purpose}{status}", ""]
        lines += [f"- *{layer}*: {text}" for layer, text in c.layers.items()]
    lines += [
        "",
        "Gates: code validators → rule-based pre-filter → output checker (call 7) → human approval "
        "(track content, method cards) → teacher flag. Badges: *Checked ✓* after the first two "
        "automatic gates, *Checked ✓ · Reviewed ✓* after a human approves too. Details: "
        "[docs/guardrails.md](docs/guardrails.md), [docs/architecture.md](docs/architecture.md). "
        "Live map: `GET /api/judge/ai-map`; audit trail: `GET /api/judge/audit`.",
    ]
    assert tuple(LAYERS) == ("input", "processing", "guardrails", "evaluation", "output")
    return "\n".join(lines)


def build(current: str) -> str:
    if START in current and END in current:
        head, rest = current.split(START, 1)
        _, tail = rest.split(END, 1)
    else:
        marker = "## Where AI is used\n"
        i = current.index(marker) + len(marker)
        j = current.index("\n## ", i)
        head, tail = current[:i] + "\n", "\n" + current[j:]
    return f"{head}{START}\n{render()}\n{END}{tail}"


def main(argv: list[str]) -> int:
    current = README.read_text(encoding="utf-8")
    new = build(current)
    if "--check" in argv:
        if new != current:
            print("README.md is out of date: run `python tasks.py readme`")
            return 1
        print("ok    README.md")
        return 0
    README.write_text(new, encoding="utf-8", newline="\n")
    print("README.md: Where AI is used regenerated")
    return 0


if __name__ == "__main__":
    raise SystemExit(main(sys.argv[1:]))
